function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 2000) return 'words needs 1 to 2000 entries.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,7}$/.test(w))) return 'Each word has 1 to 7 lowercase letters.';
  return null;
}

