function minimumLengthEncoding(words) {
  const root = new Map();
  const ends = new Map();

  for (const word of new Set(words)) {
    let node = root;
    for (let i = word.length - 1; i >= 0; i--) {
      if (!node.has(word[i])) {
        node.set(word[i], new Map());
      }
      node = node.get(word[i]);
    }
    ends.set(word, node);
  }

  let length = 0;
  for (const [word, node] of ends) {
    if (node.size === 0) {
      length += word.length + 1;
    }
  }
  return length;
}

