function minimumLengthEncoding(words) {
  const unique = [...new Set(words)];
  let total = 0;
  for (const word of unique) {
    const hidden = unique.some(other => other !== word && other.endsWith(word));
    if (!hidden) total += word.length + 1;
  }
  return total;
}

