function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = letters.slice(0, size === 'small' ? 1 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 25));
  const longest = size === 'small' ? 1 + Math.floor(rand() * 4) : 7;
  const count = size === 'small' ? 1 + Math.floor(rand() * 8) : 2000;
  const words = [];
  for (let k = 0; k < count; k++) {
    const length = 1 + Math.floor(rand() * longest);
    let word = '';
    for (let i = 0; i < length; i++) word += alphabet[Math.floor(rand() * alphabet.length)];
    words.push(word);
  }
  return [words];
}
